 /**
  * Quiz Component logic using a simple functional approach.
  */

 const quizData = [
     {
         id: "q1",
         question: "Which of these are functional programming languages?",
         choices: [
             { id: "haskell", label: "Haskell" },
             { id: "scala", label: "Scala" },
             { id: "java", label: "Java" },
             { id: "c", label: "C" }
         ],
         help: "Functional languages treat computation as the evaluation of mathematical functions."
     },
     {
         id: "q2",
         question: "Which languages are primarily used for web development?",
         choices: [
             { id: "js", label: "JavaScript" },
             { id: "python", label: "Python" },
             { id: "php", label: "PHP" },
             { id: "assembly", label: "Assembly" }
         ]
     },
     {
         id: "q3",
         question: "Which of these are systems programming languages?",
         choices: [
             { id: "c-lang", label: "C" },
             { id: "rust", label: "Rust" },
             { id: "cpp", label: "C++" },
             { id: "ruby", label: "Ruby" }
         ]
     }
 ];

 function Checkbox({ id, label, name }) {
     return `
         <div class="checkbox-item">
             <input type="checkbox" id="${id}" name="${name}" value="${id}">
             <label for="${id}">${label}</label>
         </div>
     `;
 }

 function Question({ id, question, choices, help, index }) {
     const helpId = help ? `${id}-help` : null;
     return `
         <div class="form-field">
             <fieldset ${helpId ? `aria-describedby="${helpId}"` : ""}>
                 <legend>${question}</legend>
                 ${help ? `<small id="${helpId}" class="help-text">${help}</small>` : ""}
                 <div class="options">
                     ${choices.map(choice => Checkbox({ 
                         id: choice.id, 
                         label: choice.label, 
                         name: id 
                     })).join("")}
                 </div>
             </fieldset>
         </div>
     `;
 }

 function App() {
     return `
         <main id="main-content">
             <h1>Computer Languages Quiz</h1>
             <form id="quiz-form">
                 ${quizData.map((q, index) => Question({ ...q, index })).join("")}
                 <button type="submit">Submit Quiz</button>
             </form>
             <div id="result" aria-live="polite"></div>
         </main>
     `;
 }

 function render() {
     const root = document.getElementById("root");
     root.innerHTML = App();

     const form = document.getElementById("quiz-form");
     form.addEventListener("submit", (e) => {
         e.preventDefault();
         const formData = new FormData(form);
         const results = {};
         quizData.forEach(q => {
             results[q.id] = formData.getAll(q.id);
         });

         const resultDiv = document.getElementById("result");
         resultDiv.textContent = "Thank you for completing the quiz!";
         resultDiv.className = "success";

         console.log("Quiz Results:", results);
     });
 }

 // Initial render
 render();

')

